classdef GeneratedClassTest < matlab.unittest.TestCase
% GeneratedClassTest - Tests for option classes generated by optionspec.generateClasses.
%
%   The classes are generated from the fixtures in tests/fixtures/definitions.
%   The conformance tests set the same values through a generated class and
%   through optionspec.Definition/validate, and expect the same verdict and
%   the same canonical values.

    properties
        OutputFolder (1,1) string
        TemporaryFolder (1,1) string
        ValueTypes optionspec.Definition
        Normcorre optionspec.Definition
    end

    properties (TestParameter)
        DefinitionFile = {"normcorre.json", "suite2p.json", "extract.json", "backup.json", ...
            "fov-manager.json", "value-types.json", fullfile("composition", "normcorre-processor.json")}
    end

    methods (TestClassSetup)
        function generateFixtureClasses(testCase)
            fixture = testCase.applyFixture(matlab.unittest.fixtures.TemporaryFolderFixture);
            testCase.OutputFolder = fixture.Folder;
            for i = 1:numel(testCase.DefinitionFile)
                optionspec.generateClasses(optionspectest.fixtureFile("definitions", ...
                    testCase.DefinitionFile{i}), testCase.OutputFolder, Namespace="gentest");
            end
            testCase.applyFixture(matlab.unittest.fixtures.PathFixture(testCase.OutputFolder));
            testCase.ValueTypes = optionspec.Definition( ...
                optionspectest.fixtureFile("definitions", "value-types.json"));
            testCase.Normcorre = optionspec.Definition( ...
                optionspectest.fixtureFile("definitions", "normcorre.json"));
        end
    end

    methods (TestMethodSetup)
        function createTemporaryFolder(testCase)
            fixture = testCase.applyFixture(matlab.unittest.fixtures.TemporaryFolderFixture);
            testCase.TemporaryFolder = fixture.Folder;
        end
    end

    methods (Test)
        function testDefaultsMatchDefinition(testCase, DefinitionFile)
            definition = optionspec.Definition(optionspectest.fixtureFile("definitions", DefinitionFile));
            options = createOptions(definition);
            testCase.verifyEqual(options.toStruct(), definition.defaults())
            testCase.verifyEqual(options.DefinitionId, definition.Id)
            testCase.verifyEqual(options.DefinitionVersion, definition.Version)
        end

        function testGeneratedFilesHaveNoCodeAnalyzerIssues(testCase)
            files = dir(fullfile(testCase.OutputFolder, "+gentest", "*.m"));
            testCase.verifyNotEmpty(files)
            for i = 1:numel(files)
                filePath = fullfile(files(i).folder, files(i).name);
                messages = checkcode(filePath);
                testCase.verifyEmpty(messages, files(i).name + ": " ...
                    + strjoin(string({messages.message}), "; "))
            end
        end

        function testGeneratedFilesMatch(testCase, DefinitionFile)
            problems = optionspec.checkGeneratedClasses(optionspectest.fixtureFile( ...
                "definitions", DefinitionFile), testCase.OutputFolder, Namespace="gentest");
            testCase.verifyEmpty(problems)
        end

        function testValidValuesConformToDefinition(testCase)
            % Each row: option, value; the class and validate must agree on
            % the canonical value
            cases = {
                "count", int8(5)
                "ratio", single(0.5)
                "label", "text"
                "emptyLabel", ""
                "choice", "serial"
                "optionalLabel", "set"
                "optionalLabel", []
                "optionalCount", []
                "optionalCount", 4
                "optionalRange", []
                "optionalVector", [1; 2]
                "upperBound", Inf
                "lowerBound", Inf
                "chunkLength", NaN
                "chunkLength", 5
                "interval", [2; 10]
                "weights", [0.2; 0.8]
                "indices", []
                "flags", [true; true]
                "names", {'x'; 'y'}
                "names", "x"
                "noNames", {}
                "kernel", [1, 2; 3, 4]
                "mask", [true, false; false, true]
                "emptyMatrix", []
                "Outer", struct("Inner", struct("depth", 7))
                };
            for i = 1:height(cases)
                diagnostic = sprintf("Case %d: %s", i, cases{i, 1});
                options = gentest.ValueTypesOptions();
                options.(cases{i, 1}) = cases{i, 2};
                values = testCase.ValueTypes.defaults();
                values.(cases{i, 1}) = cases{i, 2};
                testCase.verifyEqual(options.toStruct(), testCase.ValueTypes.validate(values), diagnostic)
            end
        end

        function testInvalidValuesConformToDefinition(testCase)
            cases = {
                "count", 2.5
                "count", [1, 2]
                "count", Inf
                "ratio", NaN
                "label", ['ab'; 'cd']
                "choice", 'parallel'
                "level", 3
                "lowerBound", NaN
                "chunkLength", 0
                "chunkLength", Inf
                "interval", [1, 2, 3]
                "interval", [0, Inf]
                "interval", [1, -Inf]
                "weights", [1, 2; 3, 4]
                "optionalCount", [1, 2]
                "optionalLabel", 3
                "optionalVector", [1, 2; 3, 4]
                "optionalRange", 1.5
                "kernel", ones(2, 2, 2)
                "Outer", struct("Inner", struct("depth", 1.5))
                "Outer", struct("Missing", 1)
                };
            for i = 1:height(cases)
                diagnostic = sprintf("Case %d: %s", i, cases{i, 1});
                values = testCase.ValueTypes.defaults();
                values.(cases{i, 1}) = cases{i, 2};
                testCase.verifyFalse(testCase.ValueTypes.isValid(values), diagnostic)
                testCase.verifyError(@() setOption(gentest.ValueTypesOptions(), cases{i, 1}, cases{i, 2}), ...
                    ?MException, diagnostic)
            end
        end

        function testClassConvertsCompatibleValues(testCase)
            % MATLAB converts these when it sets a property, where
            % Definition/validate rejects a value of the wrong class
            cases = {
                "flag", 1, true
                "count", true, 1
                "count", "3", 3
                "label", 3, char(3)
                "names", 'ab', "ab"
                };
            for i = 1:height(cases)
                diagnostic = sprintf("Case %d: %s", i, cases{i, 1});
                options = gentest.ValueTypesOptions();
                options.(cases{i, 1}) = cases{i, 2};
                testCase.verifyEqual(options.(cases{i, 1}), cases{i, 3}, diagnostic)
                values = testCase.ValueTypes.defaults();
                values.(cases{i, 1}) = cases{i, 2};
                testCase.verifyFalse(testCase.ValueTypes.isValid(values), diagnostic)
            end
        end

        function testConstructorWithStructAndNameValue(testCase)
            options = gentest.NormcorreOptions(struct("Configuration", struct("numRows", 2)), ...
                Misc=struct("Verbose", true));
            expected = testCase.Normcorre.defaults();
            expected.Configuration.numRows = 2;
            expected.Misc.Verbose = true;
            testCase.verifyEqual(options.toStruct(), expected)

            group = gentest.NormcorreCorrectionOptions(shiftsMethod="cubic", phaseFlag=true);
            testCase.verifyEqual(group.shiftsMethod, 'cubic')
            testCase.verifyTrue(group.phaseFlag)
        end

        function testUnknownOptionIsAnError(testCase)
            testCase.verifyError(@() gentest.NormcorreOptions(struct("Grid", struct())), ...
                "OPTIONSPEC:UnknownOption")
            testCase.verifyError(@() gentest.NormcorreTemplateOptions(struct("binwidth", 1)), ...
                "OPTIONSPEC:UnknownOption")
        end

        function testGroupAssignedFromPartialStruct(testCase)
            options = gentest.NormcorreOptions();
            options.Correction = struct("numIterations", 3);
            testCase.verifyEqual(options.Correction.numIterations, 3)
            testCase.verifyEqual(options.Correction.maximumShift, [40, 40, 5])
        end

        function testDocumentRoundTrip(testCase)
            options = gentest.NormcorreOptions();
            options.Correction.maximumShift = [10, 10, 2];
            options.Correction.boundary = "zero";
            filePath = fullfile(testCase.TemporaryFolder, "options.json");
            testCase.Normcorre.writeDocument(filePath, options.toStruct());
            readOptions = gentest.NormcorreOptions(testCase.Normcorre.readDocument(filePath));
            testCase.verifyEqual(readOptions, options)
        end

        function testUpgradedValuesConstructClass(testCase)
            values = testCase.Normcorre.readDocument( ...
                optionspectest.fixtureFile("documents", "normcorre-1.2.0.json"));
            options = gentest.NormcorreOptions(values);
            testCase.verifyEqual(options.Configuration.gridUpsampling, [2, 2, 1])
            testCase.verifyEqual(options.toStruct(), values)
        end

        function testComposedClassHasNarrowedOptions(testCase)
            options = gentest.NormcorreProcessorOptions();
            testCase.verifyEqual(options.Run.numFramesPerPart, 500)
            testCase.verifyEqual(options.Export.OutputFormat, 'Tiff')
            testCase.verifyError(@() setOption(options.Run, "ChannelProcessingMode", "single"), ?MException)
            stackRun = gentest.NormcorreProcessorRunOptions(ChannelProcessingMode="batch");
            testCase.verifyEqual(stackRun.ChannelProcessingMode, 'batch')
        end

        function testHelpTextFromDefinition(testCase)
            helpText = help("gentest.Suite2pNeuropilOptions.radius");
            testCase.verifySubstring(helpText, 'Outer radius of the neuropil mask')
            testCase.verifySubstring(helpText, 'Allows Inf')
            classHelp = help("gentest.NormcorreOptions");
            testCase.verifySubstring(classHelp, 'NoRMCorre motion correction')
            testCase.verifySubstring(classHelp, 'fixtures.normcorre')
        end

        function testFilesAndNames(testCase)
            filePaths = optionspec.generateClasses(optionspectest.fixtureFile("definitions", ...
                "fov-manager.json"), testCase.TemporaryFolder, Namespace="my.options");
            [~, names] = fileparts(filePaths);
            testCase.verifyEqual(names, ["FovManagerOptions", "FovManagerFovOrientationOptions"])
            testCase.verifyTrue(all(contains(filePaths, fullfile("+my", "+options"))))

            filePaths = optionspec.generateClasses(optionspectest.fixtureFile("definitions", ...
                "backup.json"), testCase.TemporaryFolder, BaseName="DataBackup");
            testCase.verifyEqual(filePaths, string(fullfile(testCase.TemporaryFolder, "DataBackupOptions.m")))
        end

        function testRegenerationAndChecks(testCase)
            definitionFile = optionspectest.fixtureFile("definitions", "fov-manager.json");
            filePaths = optionspec.generateClasses(definitionFile, testCase.TemporaryFolder);
            testCase.verifyEmpty(optionspec.checkGeneratedClasses(definitionFile, testCase.TemporaryFolder))

            % A changed file differs; regenerating replaces it
            writeText(filePaths(1), readText(filePaths(1)) + "% edited" + newline);
            problems = optionspec.checkGeneratedClasses(definitionFile, testCase.TemporaryFolder);
            testCase.verifySubstring(char(strjoin(problems)), 'differs from definition')
            optionspec.generateClasses(definitionFile, testCase.TemporaryFolder);
            testCase.verifyEmpty(optionspec.checkGeneratedClasses(definitionFile, testCase.TemporaryFolder))

            % A missing file
            delete(filePaths(2))
            problems = optionspec.checkGeneratedClasses(definitionFile, testCase.TemporaryFolder);
            testCase.verifySubstring(char(strjoin(problems)), 'missing')
            optionspec.generateClasses(definitionFile, testCase.TemporaryFolder);

            % A file generated from the definition but no longer generated
            staleFile = fullfile(testCase.TemporaryFolder, "FovManagerOldGroupOptions.m");
            writeText(staleFile, replace(readText(filePaths(2)), ...
                "FovManagerFovOrientationOptions", "FovManagerOldGroupOptions"));
            problems = optionspec.checkGeneratedClasses(definitionFile, testCase.TemporaryFolder);
            testCase.verifySubstring(char(strjoin(problems)), 'no longer generated')
        end

        function testHandWrittenFileIsNotReplaced(testCase)
            filePath = fullfile(testCase.TemporaryFolder, "BackupOptions.m");
            writeText(filePath, "classdef BackupOptions" + newline + "end" + newline);
            testCase.verifyError(@() optionspec.generateClasses(optionspectest.fixtureFile( ...
                "definitions", "backup.json"), testCase.TemporaryFolder), "OPTIONSPEC:FileExists")
            testCase.verifySubstring(char(readText(filePath)), 'classdef BackupOptions')
        end

        function testNameErrors(testCase)
            definitionFile = optionspectest.fixtureFile("definitions", "backup.json");
            testCase.verifyError(@() optionspec.generateClasses(definitionFile, testCase.TemporaryFolder, ...
                BaseName="1Backup"), "OPTIONSPEC:InvalidBaseName")
            testCase.verifyError(@() optionspec.generateClasses(definitionFile, testCase.TemporaryFolder, ...
                Namespace="my..options"), "OPTIONSPEC:InvalidNamespace")
            testCase.verifyError(@() optionspec.generateClasses("missing.json", testCase.TemporaryFolder), ...
                "OPTIONSPEC:InvalidDefinitionArgument")

            reserved = optionspectest.writeDefinition(testCase.TemporaryFolder, "reserved.json", ...
                '{"toStruct": {"type": "boolean", "default": true}}');
            testCase.verifyError(@() optionspec.generateClasses(reserved, testCase.TemporaryFolder), ...
                "OPTIONSPEC:ReservedOptionName")

            % Group A with group B inside, and group AB, both give the class XABOptions
            conflict = optionspectest.writeDefinition(testCase.TemporaryFolder, "conflict.json", ...
                ['{"A": {"type": "object", "properties": {"B": {"type": "object", "properties": ' ...
                '{"c": {"type": "number", "default": 1}}}}}, ' ...
                '"AB": {"type": "object", "properties": {"c": {"type": "number", "default": 1}}}}']);
            testCase.verifyError(@() optionspec.generateClasses(conflict, testCase.TemporaryFolder, ...
                BaseName="X"), "OPTIONSPEC:ClassNameConflict")
        end

        function testExampleDefinitionGenerates(testCase)
            definitionFile = fullfile(optionspec.toolboxdir(), "examples", "definitions", "rigid-registration.json");
            filePaths = optionspec.generateClasses(definitionFile, testCase.TemporaryFolder, Namespace="example");
            testCase.verifyNumElements(filePaths, 3)
            testCase.applyFixture(matlab.unittest.fixtures.PathFixture(testCase.TemporaryFolder));
            options = example.RigidRegistrationOptions();
            testCase.verifyEqual(options.Stack.TimepointInterval, [1, Inf])
            testCase.verifyEqual(options.Registration.MaxShift, Inf)
        end
    end
end

function options = createOptions(definition)
    baseName = strjoin(upper(extractBefore(split(extractAfter(definition.Id, "."), "-"), 2)) ...
        + extractAfter(split(extractAfter(definition.Id, "."), "-"), 1), "");
    options = feval("gentest." + baseName + "Options");
end

function options = setOption(options, name, value)
    options.(name) = value;
end

function text = readText(filePath)
    text = string(fileread(filePath));
end

function writeText(filePath, text)
    fileId = fopen(filePath, "w", "n", "UTF-8");
    fwrite(fileId, text, "char");
    fclose(fileId);
end
